use std::fs

fn main() {
    let text = fs::read_to_string("/dev/stdin").unwrap_or("")
    let digits = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ"
    for line in text.lines() {
        let parts: Vec<string> = line.split_whitespace().collect()
        if parts.len() < 3 { continue }
        let from: int = parts[1].parse().unwrap_or(10)
        let to: int = parts[2].parse().unwrap_or(10)
        let mut v: int = 0
        for c in parts[0].chars() {
            let ci = c as int
            let mut d = 0
            if ci >= 48 && ci <= 57 { d = ci - 48 } else { d = ci - 65 + 10 }
            v = v * from + d
        }
        if v == 0 {
            println("0")
            continue
        }
        let mut out = ""
        while v > 0 {
            let d: int = v % to
            let e: int = d + 1
            let ch = digits[d..e]
            out = "${ch}${out}"
            v = v / to
        }
        println("${out}")
    }
}

